// Fine-tuning ve Model Eğitimi cheat sheet. 10 konu; Python örnekli.
import type { Topic } from './types'

export const finetuneGiris: { q: string; a: string }[] = [
  { q: 'Fine-tuning (ince ayar) nedir?', a: 'Zaten eğitilmiş bir modeli (dil modeli, BERT, görüntü modeli) kendi örneklerinle kısa süre daha eğiterek senin işine uydurmak. Model sıfırdan öğrenmez; bildiklerinin üstüne senin istediğin üslubu, biçimi ya da alan dilini ekler. Derin Öğrenme\'deki transfer öğrenmenin dil modellerine uygulanmış halidir.' },
  { q: 'Prompt ve RAG varken neden fine-tuning?', a: 'Çoğu zaman gerekmez; önce prompt, sonra RAG dene. Fine-tuning üç durumda değer katar: her seferinde aynı biçim ve tonu garanti etmek, uzun few-shot promptu kısaltıp maliyeti düşürmek, küçük ve ucuz bir modele büyük modelin görevdeki kalitesini kazandırmak. "Bilgi öğretmek" için uygun değildir; bilgi değişince yeniden eğitmen gerekir, RAG ise anında güncellenir.' },
  { q: 'Ne zaman kesinlikle gerekmez?', a: 'Modele yeni bilgi vermek istiyorsan (RAG kullan), birkaç örnekle promptta çözülüyorsa (few-shot), elinde yüzden az örnek varsa ya da görev henüz net değilse. Fine-tuning pahalı ve zahmetlidir; veri hazırlamak eğitimden daha çok zaman alır. Önce iyi bir prompt ile başarı çizgisini ölç, sonra karar ver.' },
  { q: 'Modeli eğitmek için dev bilgisayar lazım değil mi?', a: 'Eskiden öyleydi. LoRA adlı yöntem sayesinde modelin milyarlarca ağırlığına dokunmadan küçük ek parçalar eğitilir; yüzde birden az parametre, neredeyse aynı kalite. QLoRA ile 7 milyar parametreli bir model 16 GB\'lık tek ekran kartında, hatta Colab\'da eğitilir. API fine-tuning\'de ise hiç donanım gerekmez: veriyi yüklersin, sağlayıcı eğitir.' },
  { q: 'API fine-tuning ile açık model fine-tuning arasındaki fark ne?', a: 'API yolu (OpenAI, Gemini): veri dosyasını yükle, işi başlat, bekle, ince ayarlı modelin kimliğini kullan. Kolay ama model kapalı, sağlayıcıya bağlısın. Açık model yolu (Llama, Qwen, Mistral): Hugging Face araçlarıyla kendi GPU\'nda eğitirsin; tam kontrol, veri dışarı çıkmaz, ama daha çok iş. İkisi de bu bölümde.' },
  { q: 'Ne kadar veri gerekir?', a: 'Biçim ve ton öğretmek için 100 ile 1000 arası örnek; alan diline uyarlamak için binlerce. Ama sayıdan önce kalite: model örnekleri birebir taklit eder, kötü örnek kötü davranış öğretir. 300 elle kontrol edilmiş mükemmel örnek, 1000 ortalama örnekten iyidir.' },
  { q: 'Veri nasıl görünür?', a: 'Dil modeli için sohbet biçiminde: her örnek bir sistem talimatı, bir kullanıcı mesajı ve modelin vermesini istediğin ideal cevaptan oluşur; JSONL dosyasında satır başına bir örnek. Sınıflandırma modelleri (BERT) için metin ve etiket çiftleri. Veri konusu bunu ayrıntılı gösterir.' },
  { q: 'SFT, DPO, RLHF gibi kısaltmalar ne?', a: 'SFT (denetimli ince ayar): modele ideal cevapları gösterip taklit ettirmek; ilk ve çoğu zaman tek gereken adım. DPO ve RLHF: iki cevaptan hangisinin daha iyi olduğunu öğretmek (tercih optimizasyonu); SFT\'nin üstüne ince rötuş. Çoğu iş SFT ve iyi veriyle çözülür; tercih yöntemleri ikinci aşamadır.' },
  { q: 'Fine-tuning yapınca model başka şeyleri unutur mu?', a: 'Olabilir; buna "yıkıcı unutma" denir. Dar bir veriyle uzun eğitim genel yetenekleri (özet, çeviri, akıl yürütme) zayıflatabilir. Önlemi: düşük öğrenme oranı, az epoch, veriye genel örnekler karıştırmak ve eğitim sonrası genel yetenek testleri yapmak. Değerlendirme konusu bunu işler.' },
  { q: 'Ön koşul ne?', a: 'Derin Öğrenme başlığı (eğitim döngüsü, overfitting, transfer öğrenme), LLM API (mesaj yapısı) ve Prompt Mühendisliği (iyi örnek nasıl yazılır). Açık model yolunda Python ve biraz GPU deneyimi; API yolunda sadece Python.' },
  { q: 'Hangi sırayla ilerlemeli?', a: 'Soldaki sıra: Karar (gerçekten gerekli mi) → Veri Hazırlama → API ile Fine-tune (en kolay yol) → LoRA → Hugging Face ile Eğitim → Tercih Optimizasyonu → Değerlendirme → Dağıtım → Özel Durumlar. İlk üç konu ile sonuç alırsın; LoRA ve HF açık model yolunu açar.' },
]

